# ================================================================== PART 4 · ONE TRADE, START TO FINISH
flow(id="book", part=3, scope="world",
 title="The Order Book: Where a Price Comes From",
 kick="A share has no single price. It has a list of people waiting to buy and a list of people waiting to sell, with a gap between them.",
 sum="The earlier chapters said that a share's price is the price of the last trade. This part follows one trade from beginning to end, to show how that last trade comes about and who handles it on the way.<br><br>It begins with the order book. Every share on every exchange has one. It is a running list of the prices at which people have said they will buy and the prices at which others have said they will sell. A trade happens when someone accepts a price on the other list. Once the order book is clear, terms that sound technical, such as spread, liquidity and depth, turn out to describe simple things about that list.",
 bridge="The first slide lays out the two lists and the gap between them. The second explains the two basic kinds of order and what a large order does to the price. The third explains the auctions that set the first and last price of the day.",
 out="A price comes from two lists of waiting orders, a large order moves it by eating through the list, and the day's closing price is set in a single auction. The next chapter names the firms that stand between the buyer and the seller.",
 rec="Each share has a list of buyers and a list of sellers with a gap between them, and the closing price that values every fund is set in one auction at the end of the day.",
 roles=[],
 src=[{"t": "US Securities and Exchange Commission, Investor.gov: Bid Price", "u": BID},
      {"t": "US Securities and Exchange Commission, Investor.gov: Types of Orders", "u": ORDERS},
      {"t": "Fortune, Tesla shares trading on the S&P 500 index (21 December 2020)", "u": TESLA3}],
 steps=[
  st("Today", "The whole world", WORLD, 1.15, "Bids, Asks and the Gap Between Them",
   "Picture the order book for one share as two columns. On the left are the bids, the prices buyers are offering. On the right are the asks, the prices sellers will accept. Say the best bid is 49.98 for 500 shares, with 49.97 behind it. The best ask is 50.02 for 300 shares, with 50.03 behind that. Nothing happens until someone crosses the gap. The gap, here 4 cents, is called the spread. If you must buy now, you pay 50.02. If you must sell now, you receive 49.98. Buy and sell straight back and you have lost 4 cents a share without the price changing. That loss is the cost of trading at once, and it is collected by whoever was waiting on the other side. Two more words follow from the picture. Depth is how many shares are waiting at each price. Liquidity is the general ease of trading: many orders, a narrow gap. A share with few waiting orders has a wide gap and is expensive to get into or out of.",
   BID, w=1, pl=["sec"], note="This slide shows the whole world and shades no country. The prices are invented for illustration."),
  st("Today", "The whole world", WORLD, 1.15, "Market Orders and Limit Orders",
   "There are two basic instructions you can give. The regulator's guide defines them. A market order is an order to buy or sell at once. It guarantees that you trade but not the price. A limit order names a price, and trades only at that price or better. It guarantees the price but not that you trade. The waiting orders in the book are limit orders. A market order is what uses them up. Return to the book on the last slide and send a market order to buy 1,000 shares. The first 300 are bought at 50.02. That empties the best ask, so the next shares cost 50.03, and so on up the list. The last trade, and so the quoted price, is now higher, because of nothing but the size of your order. This is why a fund buying millions of shares does not do it in one go. It splits the order into pieces, or looks for a venue where its intentions are not displayed. The next chapter comes back to those venues.",
   ORDERS, w=1, pl=["sec"], note="This slide shows the whole world and shades no country. The prices are invented for illustration."),
  st("2020", "New York", NY, 3.2, "The Opening and Closing Auctions",
   "For most of the day an exchange matches orders one by one as they arrive. At the start and the end it does something different. It collects all the orders, works out the single price at which the most shares can change hands, and trades them all at that price together. These are the opening and closing auctions. The closing one matters most, because the closing price is the official price of the day. It is used to value every fund that holds the share and to calculate every index. Funds that copy an index therefore try to trade at exactly that price. The day before Tesla joined the S&P 500 in December 2020 shows the scale this can reach. Fortune reported that almost 60 billion dollars of Tesla shares changed hands at 695 dollars each, most of it in one trade in the final seconds, at a price about 5 per cent above where the share stood just before. One moment of matching set the value used for everything else.",
   TESLA3, add={"United States": 0}, pl=["nasdaq", "spdji"]),
 ])

flow(id="middle", part=3, scope="world",
 title="The Middlemen Between You and the Seller",
 kick="An order passes through a broker and usually a trading firm before it reaches anyone who actually wants the share, and in America most never reach an exchange.",
 sum="You cannot walk up to an exchange. Between a member of the public and the other side of the trade stand several kinds of firm, each with a different job and a different way of being paid.<br><br>Knowing which is which removes much of the confusion in news about markets. It also shows something the picture of an exchange as a single open marketplace leaves out. In the largest market in the world, more than half of all share trading now takes place somewhere other than an exchange. The firms that handle that trading, and the methods they use, are covered only briefly here.",
 bridge="The first slide names the three kinds of firm and how each earns its money. The second shows where American orders actually go. The third maps how much trading each country's market carries.",
 out="A broker passes on the order, a market maker takes the other side for the spread, and in the United States over half of trading happens off the exchanges. The next chapter shows what happens after the trade is agreed.",
 rec="Brokers pass orders on, market makers take the other side and keep the spread, and more than half of American share trading in 2025 did not happen on an exchange.",
 roles=[],
 src=[{"t": "US Securities and Exchange Commission, Investor.gov: Market Makers", "u": MM},
      {"t": "Cboe Global Markets, 2025 U.S. Equities Year in Review", "u": CBOE25},
      {"t": "US Securities and Exchange Commission, Staff Report on Equity and Options Market Structure Conditions in Early 2021", "u": SECGME},
      {"t": "World Bank, Stocks traded, total value (per cent of GDP)", "u": WBD + "CM.MKT.TRAD.GD.ZS"}],
 steps=[
  st("Today", "The whole world", WORLD, 1.15, "Broker, Market Maker, Exchange",
   "Three kinds of firm handle an order. The broker is the firm you have an account with. It takes your order and passes it on, and it does not itself want to own the share. The exchange is the venue that keeps the order book and matches buyers with sellers. The market maker is a trading firm that stands ready to do both at once: it posts a price at which it will buy and a slightly higher price at which it will sell, all day, in thousands of shares. It is the reason there is nearly always someone to trade with. Its income is the gap. Buying at 49.98 and selling at 50.02, again and again, it earns 4 cents a share with little interest in where the price goes. That service has a condition worth remembering. A market maker stays only while it can earn the gap safely. When prices move violently it widens the gap or steps away, which is exactly when everyone else most wants to trade. The crash chapters return to this.",
   MM, w=1, pl=["sec"], note="This slide shows the whole world and shades no country. The prices are invented for illustration."),
  st("2025", "United States", [-96, 39], 2.6, "Most American Trading No Longer Happens on an Exchange",
   "An order does not have to go to an exchange. A broker may send it to a large trading firm that fills it from its own stock, or to a private venue where orders are matched without being displayed first. Both are called off-exchange trading. Cboe, which operates several American exchanges, reported that in 2025 off-exchange trading reached 50.6 per cent of all American share volume, the first year it passed half. The regulator's staff describe the usual route for the public: retail brokers commonly send individual investors' orders to off-exchange market makers. This matters for what a price means. The price everyone quotes comes from the orders displayed on exchanges. If most trading happens elsewhere, that public price is formed by the smaller part of the market, and the larger part borrows it without adding its own orders to the display. The arrangements behind this, including the payments brokers receive for their customers' orders, are a subject of their own and are only noted here.",
   CBOE25, add={"United States": 0}, ex=["cboe"], pl=["cboe", "sec"]),
  st("Latest year", "Every country with a figure", WORLD, 1.15, "How Much Trading Each Country's Market Carries",
   "The World Bank also publishes the value of shares traded in each country in a year, as a percentage of GDP. The map shades %(trad_n)s countries. In China the figure for 2025 was 304 per cent, in Japan 188 and in the United States 180. In India it was 73, in Germany 29 and in Nigeria about 1. In %(trad_low)s countries it was under 5. The exchange federation's monthly totals show the same concentration: of roughly 25 trillion dollars traded on its members in September 2026, 13.3 trillion was in the Americas, 10.5 trillion in Asia and the Pacific, and 1.1 trillion in Europe, the Middle East and Africa together. Where little is traded, the order book is thin. A single large order can move the price a long way, and a quoted price may be days old. Many countries on the map have a stock exchange in this condition. It lists companies and publishes prices, but there is too little trading for those prices to carry much information.",
   WBD + "CM.MKT.TRAD.GD.ZS", data={"k": "trad", "only": None}, pl=["wfe"]),
 ])

flow(id="settle", part=3, scope="world",
 title="After the Click: Clearing and Settlement",
 kick="A trade is a promise. The shares and the money change hands a day later, and a little-known institution stands in the middle guaranteeing both sides.",
 sum="When you press buy and the screen says done, nothing has yet been delivered. You have a contract. The seller still has the shares and you still have the money. Completing the exchange is called settlement, and the system that does it is the least visible part of the stock market.<br><br>It is worth understanding for one reason above all. The rules of this back office decide how much money each broker must put up as security, and so they decide, on a bad day, whether a broker can keep accepting orders at all. In January 2021 they did exactly that, and the customers of several brokers found the buy button switched off.",
 bridge="The first slide explains settlement and maps the countries that have shortened it to one day. The second explains the clearing house that guarantees each trade. The third shows the day those guarantees stopped customers from buying.",
 out="A trade settles a day or two after it is agreed, a clearing house guarantees it in the meantime and demands security from brokers, and that demand can close the market to ordinary customers. The next part turns to what the price itself means.",
 rec="Trades settle a day or two later through a clearing house that demands security from brokers, and in January 2021 that demand led brokers to stop their customers buying.",
 roles=["Settles the next day (since May 2024)", "Moves to next-day settlement on 11 October 2027"],
 src=[{"t": "DTCC, The Future of Trade Settlement", "u": DTCC},
      {"t": "SIFMA, Settlement Cycles", "u": SIFMA},
      {"t": "US Securities and Exchange Commission, Staff Report on Equity and Options Market Structure Conditions in Early 2021", "u": SECGME},
      {"t": "TechCrunch, Robinhood almost imploded during the GameStop meme stock chaos (27 June 2022), reporting the House Financial Services Committee staff report", "u": HOUSE}],
 steps=[
  st("2024 to 2027", "The North Atlantic", [-38, 46], 1.9, "The Trade Is Not Finished When You Press Buy",
   "Settlement is the moment the shares actually move to the buyer and the money to the seller. The delay between trade and settlement is written as T plus a number of days. For years the standard was T+2, two working days. On 28 May 2024 the United States shortened it to T+1, the next working day, with Canada and Mexico moving in the same month. The United Kingdom, the European Union, Switzerland and Liechtenstein have set 11 October 2027 for the same change. The delay exists because behind one trade there are several firms that must each confirm the details and find the shares and the cash. It matters because for as long as a trade is unsettled, each side is exposed to the other failing. If the price collapses overnight, a buyer may be unable or unwilling to pay. Shortening the delay shortens that exposure. The next slide shows what covers the exposure that remains.",
   DTCC, add=dict([("United States", 0), ("Canada", 0), ("Mexico", 0), ("United Kingdom", 1), ("Switzerland", 1), ("Liechtenstein", 1)] + [(c, 1) for c in EU27]), pl=["dtcc", "euroclear"],
   note="The countries named in the two sources are shaded: the three that moved in May 2024, and the United Kingdom, Switzerland, Liechtenstein and the 27 members of the European Union, which move in October 2027. Other countries are left clear because the sources do not cover them, not because they settle more slowly. The ringed circles are two large settlement bodies, DTCC and Euroclear."),
  st("Today", "New York", NY, 3.2, "The Clearing House Stands in the Middle",
   "To remove the risk of the other side failing, markets place an institution between every buyer and seller. It is called a clearing house, or central counterparty. The regulator's staff describe it as the buyer to every seller and the seller to every buyer. Once a trade is agreed, you are no longer relying on a stranger. You are relying on the clearing house. The staff report gives an example: if a share bought at 100 has fallen to 20 by settlement day, the buyer might want to walk away, and the clearing house guarantees the seller that the trade will still go through. To be able to make that promise, it requires every broker that uses it to deposit money in advance, called margin. The more a broker's customers are trading, and the more violently prices are moving, the more it must deposit. In the United States the clearing house for shares is the NSCC, part of a company called DTCC. Brokers are told how much to deposit, sometimes within hours.",
   SECGME, add={"United States": 0}, pl=["dtcc", "sec"], ex=["secgme"]),
  st("January 2021", "New York", NY, 3.2, "The Day the Back Office Stopped the Buying",
   "In January 2021 hundreds of thousands of small investors bought shares in GameStop, a video game retailer, and the price rose from under 20 dollars to an intraday high of 483 on 28 January. The clearing house saw brokers whose customers were buying a share that might collapse before settlement. On 27 January, the regulator's staff report says, it issued same-day margin calls to 36 brokers totalling 6.9 billion dollars. A congressional staff report later found that the broker Robinhood had about 696 million dollars on deposit that morning and faced a shortfall of about 3 billion. On 28 January Robinhood and other brokers stopped customers from buying GameStop and several other shares, while still letting them sell. The price fell. The regulator's staff note that the clearing house has no power to order this. The brokers chose it, in some cases in reaction to the margin demands. So whether the public could buy a share was decided by a collateral rule in an institution most of them had never heard of.",
   SECGME, add={"United States": 0}, pl=["dtcc", "robinhood", "sec"], ex=["secgme"]),
 ])

# ================================================================== PART 5 · HOW A PRICE IS MADE, AND HOW IT IS BENT
flow(id="inside", part=4, scope="world",
 title="What a Price Should Tell You, and the Push From Inside",
 kick="A share price is supposed to be the pooled judgement of many investors. The company being judged has several ways of leaning on the scale.",
 sum="The mechanics are now in place. A share is a claim on future profit. Its price is the latest trade in an order book. The trade reaches the book through brokers and market makers and is completed by a clearing house. From here the map asks a harder question: what does the price mean, and how reliable is it?<br><br>The standard answer is that the price gathers up what thousands of independent buyers and sellers know and believe, and so it is the best available estimate of what a company is worth. Finding that estimate through trading is called price discovery. It depends on the traders judging for themselves and on the company not steering the result. This chapter looks at the second condition. The next looks at the first.",
 bridge="The first slide sets out what a price is meant to do. The second shows a company raising its profit per share by spending cash. The third shows managers shaping the reported profit itself. The fourth explains the short seller, the one trader paid to find a price that is too high. The fifth shows a price that broke loose from the business altogether.",
 out="A price is meant to pool independent judgements about future profit, but companies buy their own shares and smooth their own results, and trading contests can carry a price far from the business. The next chapter looks at buyers who do not judge at all.",
 rec="Companies spent a trillion dollars in a year buying their own shares, most finance chiefs say they would give up real value for smoother results, and a contest between traders can detach a price from the business.",
 roles=[],
 src=[{"t": "S&P Dow Jones Indices, S&P 500 buybacks, third quarter of 2025 (18 December 2025)", "u": SPBB},
      {"t": "J. Graham, C. Harvey and S. Rajgopal, The Economic Implications of Corporate Financial Reporting (NBER Working Paper 10550)", "u": GHR},
      {"t": "US Securities and Exchange Commission, Staff Report on Equity and Options Market Structure Conditions in Early 2021", "u": SECGME}],
 steps=[
  st("Today", "The whole world", WORLD, 1.15, "The Idea: Many Independent Judgements, Pooled",
   "Here is the case for trusting a share price. Each buyer and seller knows something. One has studied the accounts, another works in the industry, a third has counted the lorries leaving the factory. Each trades on what they know. A buyer who thinks the share is cheap pushes the price up a little, and a seller who thinks it dear pushes it down. The price that results holds a trace of everything the traders knew. No single person could have gathered it. That is price discovery, and when it works a share price is a useful signal. It tells managers whether investors approve of their plans and it steers new money toward firms that can use it. Three things have to be true for it to work. The traders must be judging the company for themselves. The orders must be visible enough for others to react to. And the information they judge by, above all the company's reported profit, must not be arranged by the company to produce a wanted price. The rest of this part tests each of these.",
   MCAPDEF, w=1, note="This slide shows the whole world and shades no country, because it sets out an idea. Nothing on it is measured."),
  st("2025", "New York", NY, 3.0, "Buybacks: A Company Buys Its Own Shares",
   "A company with spare cash can use it to buy its own shares on the market and cancel them. This is a buyback. S&P Dow Jones Indices reports that the companies in the S&P 500 spent a record 1.02 trillion dollars on buybacks in the twelve months to September 2025. In the third quarter alone they spent 249 billion, against 168 billion on dividends. Twenty companies did about half of that quarter's buying, and Apple spent 96.7 billion in the year. A buyback changes a number that matters. Take a company with 100 million shares and a profit of 500 million. Its earnings per share are 5. It buys back and cancels 10 million shares. Profit is unchanged, but earnings per share are now 5.56, a rise of 11 per cent, and the company was itself a large buyer pushing on the price while it happened. Earnings per share is the figure analysts watch and a figure executives' pay is often tied to. A buyback raises it without the company selling one more product.",
   SPBB, add={"United States": 0}, pl=["spdji"], ex=["buybacks"]),
  st("2005", "United States", [-96, 39], 2.6, "Smoothing the Numbers",
   "Listed companies report their profit every three months. Before each report, analysts at banks publish a forecast, and the share price then moves on whether the company beat the forecast or missed it. Managers know this and manage to it. Three accounting professors, Graham, Harvey and Rajgopal, surveyed 401 senior finance executives of American companies about how they handle it. Their paper reports that 78 per cent said they would give up economic value in exchange for smooth earnings. The paper lists what that means in practice: putting off maintenance, cutting research or advertising, or delaying a worthwhile project so that this quarter's figure lands where the market expects. This turns the purpose of a share price upside down. The price is supposed to reward a company for being run well. Here the company is run less well, by its own executives' account, in order to protect the price. And the reported profit that traders rely on is partly a product of that effort.",
   GHR, add={"United States": 0}, ex=["ghr"]),
  st("Today", "The whole world", WORLD, 1.15, "Short Selling: Betting on a Fall",
   "Most investors profit when a price rises. A short seller profits when it falls. The method is to borrow shares from an existing holder for a fee, sell them at once, and buy them back later to return them. Borrow and sell at 100, buy back at 60, and you keep 40, less the fee. If the price rises instead you must still buy the shares back, at whatever they cost. A buyer can lose only what was paid. A short seller's loss has no ceiling. The amount of a company's shares currently sold short is called short interest. Short sellers are unpopular with companies, and governments often restrict them when markets fall. But they do a job nobody else is paid for. Everyone who owns a share gains if its price is too high. Only the short seller gains from showing that it is. Where short selling is difficult or banned, bad news reaches a price more slowly, and the pooling of judgements described three slides ago is missing its sceptics.",
   SECGME, w=1, pl=["sec"], note="This slide shows the whole world and shades no country. The prices are invented for illustration. The regulator's staff report is cited for its account of how shares are lent and sold short."),
  st("January 2021", "New York", NY, 3.2, "The Squeeze: A Price That Left the Business Behind",
   "GameStop shows what happens when short selling and buying collide. The regulator's staff found that in January 2021 the shares sold short came to 122.97 per cent of the shares available to trade. That is possible because a share that has been borrowed and sold can be lent again by its new owner. Small investors, organising on social media, saw that the short sellers would have to buy if the price rose, and bought. From its low on 8 January to its high on 28 January the price rose about 2,700 per cent. Nearly 900,000 separate accounts traded the share on 27 January, up from under 10,000 at the start of the month. The staff concluded that buying by short sellers was a small part of the volume and that it was positive sentiment that kept the price up for weeks. Nothing comparable happened to the shop chain's sales in those weeks. The price was recording a contest between groups of traders. It told a reader nothing about the business.",
   SECGME, add={"United States": 0}, pl=["sec", "robinhood"], ex=["secgme"]),
 ])

flow(id="index", part=4, scope="world",
 title="The Index Decides",
 kick="More than half of fund money now buys whatever is on a list. The firms that write the lists can move a company's price, or a country's market, with an announcement.",
 sum="The last chapter tested whether companies leave their own price alone. This one tests the other condition: that the buyers are judging for themselves.<br><br>A passive fund does not judge. It buys every share on its index in proportion, at whatever price, and sells only when the index changes. That is cheap and sensible for the saver. But as more money is run this way, more of each day's buying is done by funds that have no opinion about the price they pay. And the decisions that do move that money are taken by the index providers, a few private companies whose choices about which firms and which countries are on the list are followed automatically by trillions of dollars.",
 bridge="The first slide shows how much money now follows lists and what research says that does to prices. The second follows one company joining one list. The third shows an index firm's warning emptying a national market. The fourth shows the same firm sorting the world's countries into classes.",
 out="When money follows lists, the price of joining or leaving a list is set by the announcement and not by the business, and a private company's classification can redirect investment into or out of a whole country.",
 rec="Index funds must buy what is added to a list and sell what is removed, so a list-maker's decision moved 90 billion dollars into one company in a day and cut a sixth off Indonesia's market in two.",
 roles=["Home of the index providers", "Market under review or warned in 2026", "Being moved up a class in May 2027"],
 src=[{"t": "Morningstar, US Fund Flows: Picking Up Steam in 2024", "u": MSTAR},
      {"t": "Reuters via Kitco, Global passive equity funds' assets eclipsed active in 2023 for first time (1 February 2024)", "u": LIPPER},
      {"t": "X. Gabaix and R. Koijen, In Search of the Origins of Financial Fluctuations: The Inelastic Markets Hypothesis (NBER Working Paper 28967)", "u": GK},
      {"t": "Reuters via Business Standard, Tesla debuts into S&P after frantic Friday trading (21 December 2020)", "u": TESLA2},
      {"t": "The Jakarta Post, What is MSCI and what has it done to Indonesia's stock market? (30 January 2026)", "u": JP2},
      {"t": "MSCI, Results of the MSCI 2026 Market Classification Review (23 June 2026)", "u": MSCI26}],
 steps=[
  st("2023 to 2024", "The whole world", WORLD, 1.15, "When Half the Money Buys the Whole List",
   "An earlier slide gave Morningstar's finding that index funds hold about 53 per cent of American fund assets. The pattern is worldwide. The data firm LSEG Lipper counted 15.1 trillion dollars in passive share funds across the world at the end of 2023, against 14.3 trillion in active ones, the first time passive was ahead. Think about what such a fund does when a saver pays in 100 dollars. It buys a little of every share on its list, the dear ones and the cheap ones alike, more of whichever is already biggest. It never sells a share for being overpriced. Two economists, Gabaix and Koijen, measured what this kind of buying does. They estimate that putting 1 dollar into the stock market raises the market's total value by about 5 dollars, because so few holders are willing to sell in response. If that is right, prices are moved less by news about companies than by the flow of money in and out of funds. And the price of each share depends partly on whether it is on the list.",
   GK, w=1, ex=["passive", "gk"], note="This slide shows the whole world and shades no country. The diamonds mark Morningstar in Chicago and the National Bureau of Economic Research in Cambridge, Massachusetts, which published the estimate."),
  st("November to December 2020", "New York", NY, 3.2, "One Company Joins the List",
   "The S&P 500 is not simply the 500 largest American companies. A committee at S&P Dow Jones Indices decides who joins. In September 2020 it passed over the carmaker Tesla. On 16 November it announced that Tesla would join on 21 December. Tesla made the same cars that week as the week before. But every fund copying the index now had to own it by a known date, and everyone else knew that. Reuters reported that the shares rose about 70 per cent between the announcement and the day of entry. By the close of trading on the Friday before, according to the index firm's own analyst, index funds had bought 90.3 billion dollars of Tesla shares, and had sold the same amount of other companies in the index to pay for them. It was the most valuable company ever added. Nothing in the business explains a gain of 70 per cent in five weeks. A committee's decision did, by turning a list into an order to buy.",
   TESLA2, add={"United States": 0}, pl=["spdji", "nasdaq"], ex=["tesla"]),
  st("January to November 2026", "Jakarta", JAKARTA, 2.7, "Regional Example: Indonesia, and a Warning From New York",
   "Regional Example: Index firms rank countries as well as companies. MSCI sorts national markets into developed, emerging and frontier. Funds that follow its emerging markets list must hold Indonesian shares while Indonesia is on it. On 28 January 2026 MSCI said it might move Indonesia down to frontier. Its concern was free float, the part of each company's shares that is really available to trade and not locked up by controlling owners. The Jakarta exchange halted trading that day as prices fell. The main index dropped by as much as 16.7 per cent in two days, and the head of the exchange resigned on 30 January. The authorities then doubled the minimum free float required of listed companies from 7.5 to 15 per cent. In June MSCI left Indonesia where it was but kept the review open until November. A change in the rules for every listed company in a country of about 280 million people was made on a timetable set by a company in New York.",
   JP2, add={"Indonesia": 1, "United States": 0}, arcs=[[[-74.0, 40.75], JAKARTA]], an=[("New York", "Jakarta")], reg=True, pl=["msci", "idx", "ojk"], ex=["indonesia"]),
  st("2026", "The North Atlantic", [-30, 42], 1.7, "Sorting the World's Markets Into Classes",
   "Indonesia was one decision in a yearly round. MSCI's market classification review for 2026 assessed 79 national markets against 18 measures of how easily foreign institutions can get money in and out. The firm says its framework decides whether a market is developed, emerging or frontier according to what international institutional investors actually experience. In the 2026 round it confirmed that Greece will move from emerging to developed in May 2027, the first country to regain that rank, and that Bulgaria will move up from standalone to frontier. It raised concerns about shareholder transparency in both Indonesia and Türkiye. Each class has its own index and its own funds, so a move between classes forces some funds to sell a country's shares and others to buy. Notice whose experience the test measures. A market is graded on how convenient it is for large foreign funds. A government that wants their money shapes its exchange rules, its currency rules and its ownership limits to pass.",
   MSCI26, add={"United States": 0, "Indonesia": 1, "Turkiye": 1, "Greece": 2, "Bulgaria": 2}, arcs=[[[-74.0, 40.75], ATHENS], [[-74.0, 40.75], SOFIA]], an=[("New York", "Athens"), ("New York", "Sofia")], pl=["msci", "spdji", "ftse"], ex=["indonesia"],
   note="The view is centred on the North Atlantic, between New York and the two countries being moved. Only the countries named in the source are shaded: Greece and Bulgaria, which move up a class in May 2027, and Indonesia and Türkiye, where MSCI raised concerns in 2026. The full list of which class each of the 79 markets sits in is not drawn, because the published announcement does not give it."),
 ])

# ================================================================== PART 6 · WHEN IT BREAKS
flow(id="crash", part=5, scope="world",
 title="How a Crash Works",
 kick="A crash is not a great many people changing their minds at once. It is a small fall that forces other people to sell, whose selling forces more.",
 sum="Prices fall all the time without a crash. What turns a fall into a crash is forced selling: sales made by people who have no choice, which push the price down and so force the next group to sell.<br><br>The chapters so far supply every part needed to see how. The price is set by the latest trade. Market makers step away when prices move violently. Brokers lend money against shares and must be repaid. Some investors sell by rule and not by judgement. Put those together in a falling market and each makes the others worse. The cases on the next slides are different decades and different countries. The mechanism is the same.",
 bridge="The first slide shows how borrowed money forces sales. The second is the crash of 1929, the model case. The third is 1987, when selling was done by formula. The fourth is China in 2015, when nearly half the market stopped trading.",
 out="Borrowing, selling rules and vanishing buyers turn a fall into a spiral, and the same parts appear in 1929, 1987 and 2015. The next chapter covers the devices built to stop it.",
 rec="A crash is a chain of forced sales: borrowed money in 1929, selling formulas in 1987, and in China in 2015 a market where nearly half the companies simply stopped trading.",
 roles=["Where the crash described began", "Hit hardest among the markets named"],
 src=[{"t": "Federal Reserve History, Stock Market Crash of 1929", "u": F1929},
      {"t": "Federal Reserve History, Stock Market Crash of 1987", "u": F1987},
      {"t": "France 24, Almost half of China's firms halt trading as market dives (8 July 2015)", "u": F24}],
 steps=[
  st("Today", "The whole world", WORLD, 1.15, "Borrowed Money Turns a Fall Into a Spiral",
   "A broker will lend you money to buy shares, holding the shares as security. This is buying on margin. Say you buy 100 of shares with 10 of your own and 90 borrowed. If the price rises 10 per cent you have doubled your money. If it falls 10 per cent, your 10 is gone and the shares are worth exactly what you owe. Before that point the broker demands more cash, which is called a margin call. If you cannot pay, the broker sells your shares at once, at any price, to recover the loan. Now multiply. Thousands of borrowers get the call on the same morning. Their shares are all sold into a falling market. That selling lowers the price further, which triggers the calls on the next layer of borrowers, who had more of a cushion. Meanwhile the market makers have widened their gaps or withdrawn, so each forced sale moves the price more than it would on a calm day. None of these sellers has formed a view about any company. They are selling because they must.",
   F1929, w=1, note="This slide shows the whole world and shades no country. The numbers are invented for illustration, except that a deposit of about 10 per cent was typical in 1929, as the next slide's source records."),
  st("1929 to 1932", "New York", NY, 3.2, "1929: The Model Case",
   "The Federal Reserve's own history describes the American market of the late 1920s. Brokerage houses and margin accounts let ordinary people buy shares with borrowed funds. Buyers typically put down 10 per cent of the price and borrowed the rest, with the shares as security. On Monday 28 October 1929 the Dow Jones Industrial Average, an index of leading shares, fell nearly 13 per cent. On Tuesday it fell nearly 12 per cent more. Run that through the last slide. A buyer who had put down 10 per cent was wiped out before lunch on Monday, and their broker was selling. By the middle of November the Dow had lost almost half its value. The fall did not stop there. It continued until the summer of 1932, when the index stood 89 per cent below its peak. The lending that had lifted prices on the way up was the thing that drove them down. Each buyer on margin had been a forced seller waiting for a trigger.",
   F1929, add={"United States": 0}, ex=["f1929"], pl=["nyse", "fed"]),
  st("19 October 1987", "New York to Wellington", WORLD, 1.15, "1987: Selling by Formula",
   "On 19 October 1987 the Dow fell 22.6 per cent in a single day. It remains the largest one-day fall on record. The Federal Reserve's history gives part of the reason. Large investors had adopted a product called portfolio insurance. It was a formula that used futures and options to sell automatically as the market fell, to limit losses. Each fund using it was protected only if someone was there to buy. On the day, many funds' formulas gave the same instruction at the same time, and the first losses led to further rounds of selling. The history records traders racing each other to sell. It travelled round the world within hours: in the worst case, New Zealand, the market fell 60 per cent. This is the second kind of forced seller. Nobody was repaying a loan. Investors had handed the decision to a rule, and the rule could not tell a bargain from a disaster. Every later system that trades by rule, including index funds, carries a version of this.",
   F1987, w=1, add={"United States": 0, "New Zealand": 1}, arcs=[[NY, WELLINGTON]], an=[("New York", "Wellington")], ex=["f1987"], pl=["nyse", "fed"],
   note="The United States, where the fall began, and New Zealand, the worst case the source names, are shaded. The line joins New York and Wellington the long way round, across Africa and the Indian Ocean, so that it does not split at the edge of a flat map. Turn the globe to follow it."),
  st("July 2015", "Shanghai", SHANGHAI, 3.0, "Regional Example: China, Where Half the Market Stopped",
   "Regional Example: China's markets had risen steeply through early 2015, with much of the buying done on borrowed money by small investors. In June prices turned and the margin calls began. What happened next showed another way a market can fail. Listed companies are allowed to ask the exchange to suspend trading in their own shares. As prices dropped, they did so in huge numbers. On 8 July 2015 France 24 reported that about 1,300 companies, almost half of those listed on the Shanghai and Shenzhen exchanges, had halted trading in their shares. A shareholder in one of those companies could not sell at any price. Investors who needed cash to meet margin calls therefore sold whatever they still could, which pushed down the shares that remained open. A suspended share keeps its last price on the screen. That number was not a price in any useful sense. Nobody could trade at it, and it was protecting the company's owners from seeing what a buyer would really pay.",
   F24, add={"China": 0}, reg=True, pins=[[114.055, 22.541, "Shenzhen"]], pl=["shse", "szse", "csrc"], ex=["china2015"]),
 ])

flow(id="brakes", part=5, scope="world",
 title="The Brakes, and the Rescue",
 kick="Exchanges can stop the trading. Only a government or central bank can stop the fall, and it does so by buying, which restores the wealth of whoever still holds shares.",
 sum="After 1987 exchanges built devices to interrupt a crash. They pause trading when prices fall too far too fast, on the theory that a pause lets buyers gather. These are the brakes. They change the timing of a fall. They do not supply buyers.<br><br>When a fall threatens banks, pensions or a currency, something larger steps in: the central bank or the government itself. It lends freely, or it buys shares outright with public money. This usually works, in the sense that prices recover. The last slide asks who that recovery reaches, because a rescue of share prices is a rescue of the people who own shares, in proportion to how many they own.",
 bridge="The first slide explains circuit breakers. The second shows what a halt cannot do. The third is the central bank's promise of 1987. The fourth is a government buying its own stock market in Hong Kong. The fifth is a central bank that became one of its country's largest shareholders. The sixth asks who is made whole.",
 out="Halts pause a fall, public money ends it, and the benefit goes to those who hold shares when the buying starts. The last part puts every link in one view.",
 rec="Circuit breakers pause trading but supply no buyers. Governments and central banks end crashes by buying or lending, and the gain goes to whoever still holds shares, which in America is mostly the richest tenth.",
 roles=["Where the brake or rescue described took place"],
 src=[{"t": "US Securities and Exchange Commission, Investor.gov: Stock Market Circuit Breakers", "u": CB},
      {"t": "The New York Times, Wall Street Plunges in Worst Drop Since 2008 (9 March 2020)", "u": "https://www.nytimes.com/2020/03/09/business/stock-market-today.html"},
      {"t": "The New York Times, Stock Markets Shudder After Chinese Stock Plunge Forces a Trading Halt (8 January 2016)", "u": NYT16},
      {"t": "The Jakarta Post, IDX plunges after MSCI warning about RI stocks (28 January 2026)", "u": JP1},
      {"t": "Federal Reserve History, Stock Market Crash of 1987", "u": F1987},
      {"t": "Hong Kong Monetary Authority, Asian Financial Crisis: Difficult Decisions in the Disposal of Shares After Stock Market Operation (18 September 2019)", "u": HKMA1},
      {"t": "Hong Kong Monetary Authority, The wicked month of August (3 August 2000)", "u": HKMA2},
      {"t": "Bank of Japan, Principal Terms and Conditions for the Sales of ETFs and J-REITs", "u": BOJ1},
      {"t": "The Japan Times, on the Bank of Japan's decision of 19 September 2025", "u": BOJ2},
      {"t": "Asia Asset Management, Bank of Japan to start selling ETF holdings this month (12 January 2026)", "u": BOJ3},
      {"t": "CryptoSlate, Japan's central bank will sell ETFs 2.6 times faster and could still take 43 years to exit (November 2026)", "u": BOJ4},
      {"t": "K. Shibusawa and M. Poggi, The Bank of Japan Must Define a Strategy for Its ETF Holdings (28 October 2025)", "u": "https://www.cepweb.org/?p=5825"},
      {"t": "Securities Investor Protection Corporation, What SIPC Protects", "u": SIPC},
      {"t": "Axios, on the Federal Reserve's Distributional Financial Accounts (4 June 2026)", "u": AXIOS}],
 steps=[
  st("Since 1987", "New York", NY, 3.2, "Circuit Breakers",
   "The crash of 1987 led exchanges to adopt rules that pause trading during a rapid fall. In the United States they are called market-wide circuit breakers and are measured on the S&P 500 index against the previous day's close. A fall of 7 per cent stops all share trading for 15 minutes. A fall of 13 per cent stops it for another 15. A fall of 20 per cent ends trading for the day. The first two apply only before 3.25 in the afternoon. The breakers tripped several times in March 2020, when markets fell at the start of the pandemic, including on 9 March and 18 March. China introduced a breaker of its own at the start of January 2016 and suspended it on 7 January, days later, out of concern that it was adding to investors' alarm: a market approaching the trigger gave everyone a reason to sell before the door shut. That is the difficulty in the design. A pause can calm a panic or it can become the thing people rush to beat.",
   CB, add={"United States": 0, "China": 0}, pl=["sec", "nyse", "csrc"], pins=[[SHANGHAI[0], SHANGHAI[1], "Shanghai"]],
   note="Countries whose circuit breaker is described: the United States and China. The date of China's suspension is from the New York Times of 8 January 2016. The ringed circles are the regulators and the New York Stock Exchange."),
  st("28 January 2026", "Jakarta", JAKARTA, 3.0, "Regional Example: Indonesia, and What a Halt Cannot Do",
   "Regional Example: Return to Jakarta on 28 January 2026, the day of MSCI's warning. As prices dropped, the Indonesia Stock Exchange temporarily halted trading, as its rules provide. The halt did what a halt can do. It stopped orders being matched for a time. It did not change the reason for selling. Funds that follow MSCI's list still faced the prospect of being required to sell Indonesian shares, and a pause gave them no reason to think otherwise. When trading resumed the selling resumed, and the index went on to fall by as much as 16.7 per cent over the two days. A halt works when the fall is caused by a brief shortage of buyers, a mistake, or a panic that a few minutes of thought will cure. It does nothing when sellers have a standing reason to sell. In that case it only decides which sellers get out first, and those are generally the ones with the fastest systems and the best information.",
   JP1, add={"Indonesia": 0}, reg=True, pl=["idx", "ojk"], ex=["indonesia"]),
  st("20 October 1987", "Washington", WASH, 3.2, "The Central Bank's Promise",
   "The morning after the fall of 22.6 per cent in 1987, the chairman of the Federal Reserve, the American central bank, issued one sentence. The Federal Reserve, he said, affirmed its readiness to serve as a source of liquidity to support the economic and financial system. Liquidity here means ready cash. The message was that banks could borrow whatever they needed from the central bank, and so could keep lending to the brokers and trading firms that were short of cash. Behind the scenes, the Federal Reserve's history says, it encouraged banks to continue lending on their usual terms. The market steadied. The history calls this a precedent for the central bank's use of liquidity to stem financial crises. A precedent teaches people what to expect. After 1987 anyone holding shares had reason to believe that if prices fell far enough to frighten the banks, the central bank would act. A buyer who expects to be caught will pay more and borrow more than one who does not.",
   F1987, add={"United States": 0}, pl=["fed"], ex=["f1987"]),
  st("August 1998", "Hong Kong", HK, 3.4, "Regional Example: Hong Kong Buys Its Own Stock Market",
   "Regional Example: In August 1998, during the Asian financial crisis, traders were selling Hong Kong shares and the Hong Kong dollar together. The government answered by buying the market. The Hong Kong Monetary Authority, which acts as the territory's central bank, records that over ten trading days it used 118 billion Hong Kong dollars, about 18 per cent of the public reserve it manages, to buy the 33 companies in the main index. On the last day, 28 August, it was by its own account almost the only buyer in town. The selling stopped. The government was left owning a large part of its own leading companies, and later sold most of the holding back to the public through a fund created for the purpose. By August 2000 the authority reported that it had recovered 72.5 billion and still held shares worth about 175 billion. The public purse came out ahead. So did everyone who was still holding those 33 shares on 28 August, at a price a government had set.",
   HKMA1, reg=True, pins=[[HK[0], HK[1], "Hong Kong"]], pl=["hkma", "hkex"], ex=["hk1998"]),
  st("2010 to 2026", "Tokyo", TOKYO, 3.2, "Regional Example: Japan's Central Bank as Shareholder",
   "Regional Example: Japan shows what happens when support does not end. For more than a decade the Bank of Japan bought exchange-traded funds holding Japanese shares, as part of its effort to revive the economy. It stopped buying in March 2024. At the end of September 2025 the funds it held had cost 37.1 trillion yen and were worth 83 trillion, about 534 billion dollars. One estimate puts that at roughly 7 per cent of the whole Japanese stock market. In September 2025 the Bank decided to begin selling, at about 330 billion yen a year measured at cost. Its governor said that at that pace it would take more than 100 years. In October 2026 it raised the pace to 860 billion yen a year from January 2027, which still implies about 43 years. A central bank that buys shares to support prices becomes a holder too large to sell without lowering them. Every other shareholder in Japan has had a buyer behind the market for a decade, and now has a seller who has promised to go slowly.",
   BOJ1, add={"Japan": 0}, reg=True, pl=["boj", "jpx", "fsaj"], ex=["boj"]),
  st("Today", "United States", [-96, 39], 2.6, "Who Is Made Whole",
   "Take the rescues together. In each one, public money or a public promise stopped prices falling and helped them recover. That is a gain to whoever holds shares, in proportion to how many they hold. The Federal Reserve's accounts of American household wealth, as reported in June 2026, show the richest tenth of households owning about 87 per cent of the shares held by households, and the poorer half about 1 per cent. A rescue of share prices therefore delivers about 87 per cent of its benefit to the top tenth. Now take the people a rescue misses. The borrower who was sold out by a margin call on the way down owns nothing when prices recover. The worker laid off in the slump that follows holds few shares or none. There is a scheme that protects American investors, the Securities Investor Protection Corporation, but read what it covers: up to 500,000 dollars if your broker fails and your shares go missing. It states plainly that it does not protect against a decline in the value of your securities.",
   SIPC, add={"United States": 0}, pl=["fed", "sipc"], ex=["sipc"]),
 ])

# ================================================================== PART 7 · THE WHOLE MACHINE
flow(id="chain", part=6, scope="world",
 title="The Whole Machine in One View",
 kick="From the company that sells a share to the saver whose pension holds it, every link is a business with its own interest, and the price passes through all of them.",
 sum="The story has gone link by link. This last chapter lays the links end to end, so the whole path from a company to a saver can be seen at once, and then names the bodies that operate it.<br><br>Nothing new is added here. Each sentence on the first slide is the short form of a chapter, and each figure has already been shown with its source.",
 bridge="The first slide runs the full chain in order. The second names the bodies that run the machinery and shows where on the map they sit.",
 out="",
 rec="",
 roles=[],
 src=[{"t": "World Federation of Exchanges, Market Statistics, November 2026", "u": WFE},
      {"t": "UN Sustainable Stock Exchanges initiative, Stock Exchange Database", "u": SSE},
      {"t": "Jay R. Ritter, Initial Public Offerings: Underpricing", "u": RIT},
      {"t": "US Securities and Exchange Commission, Staff Report on Equity and Options Market Structure Conditions in Early 2021", "u": SECGME}],
 steps=[
  st("Today", "The whole world", WORLD, 1.15, "From the Company to the Saver: The Chain",
   "A company sells a slice of itself once, at a price fixed in private by its banks, and the buyers the banks choose gain about a fifth on the first day. From then on the company is paid nothing. Its shares are resold on an exchange that is itself a business, under a regulator whose reach ends at the border. Each resale passes through a broker and usually a trading firm that keeps the gap between the buying and selling price, and in America more often than not it never reaches an exchange. A clearing house guarantees the trade and can, by raising its demand for security, shut ordinary buyers out. The price that comes out is the last trade, applied to every share. The company leans on it by buying its own shares and smoothing its results. More than half of fund money pays that price without judging it, following lists that a few firms write. When the price falls far enough, forced sellers drive it down, and public money brings it back for whoever still holds.",
   WFE, w=1, ex=["wfe2026"], note="This slide shows the whole world and shades no country. It restates the chapters before it and adds no new figure."),
  st("Today", "The whole world", WORLD, 1.15, "The Bodies That Run the Machinery",
   "The map now shows the %(orgs)s bodies in this story's directory, each at its headquarters, alongside the %(ex_n)s exchange dots. They fall into five groups. The exchange groups host the trading and write the listing rules. The index providers, three firms in New York and London, decide which companies and countries the passive funds must hold. The clearing and settlement bodies guarantee trades and hold the records of who owns what. The regulators and central banks license all of the above, and are the source of rescue when it comes. The brokers and trading firms carry the orders. Being on this list is not an accusation. It says only that the body is a working part of the machine. To look at them outside the story, close the story boxes and use the list on the left: each group can be switched on and off, each body opens to a short entry with its source, and each exchange dot opens to its listings, value, trading and regulator.",
   SSE, w=1, pl=["nyse", "nasdaq", "lseg", "euronext", "dboerse", "jpx", "hkex", "shse", "szse", "nse", "bse", "tadawul", "b3", "jse", "tmx", "cboe", "idx", "msci", "spdji", "ftse", "dtcc", "euroclear", "sec", "iosco", "esma", "csrc", "fsaj", "sebi", "fca", "ojk", "hkma", "boj", "fed", "sipc", "wfe", "robinhood"],
   note="Every body in the directory is drawn as a ringed circle at its headquarters, coloured by group, and every exchange in the two sources as a dot."),
 ])
